def safe_relative(name):
    require(isinstance(name, str) and name and "\\" not in name and "\0" not in name, "Invalid member name")
    path = PurePosixPath(name)
    require(not path.is_absolute() and path.as_posix() == name and all(part not in ("", ".", "..", ".git", "node_modules", ".aws", ".codex", ".agents") for part in path.parts), "Unsafe relative path")
    return path


def safe_member(name):
    path = safe_relative(name)
    require(name in SOURCE24_ALLOWED_MEMBERS and len(path.parts) >= 2 and path.parts[0] in ("workspace", "temporary"), "Destination outside the exact Source24 selection")
    return path.parts[0], PurePosixPath(*path.parts[1:])


